steps.script:
var acts = PhaseManager.get_current_phase_instance().get_available_actions()
var found = false
for a in acts:
	if a.get("type", "") == "BATTLE_SHOCK_TEST" and a.get("unit_id", "") == "U_KOMMANDOS_H":
		found = true
return found

var cc = tree.current_scene.get_node_or_null("CommandController")
if cc == null:
	return "NO_CONTROLLER"
cc._refresh_ui()
return true

var panel = SceneRefs.main_path("HUD_Right/VBoxContainer/CommandScrollContainer/CommandPanel")
if panel == null:
	return "NO_PANEL"
var sec = panel.get_node_or_null("BattleShockSection")
return sec != null and sec.is_visible_in_tree()

var panel = SceneRefs.main_path("HUD_Right/VBoxContainer/CommandScrollContainer/CommandPanel")
var sec = panel.get_node_or_null("BattleShockSection") if panel else null
if sec == null:
	return "NO_SECTION"
var cta = sec.get_node_or_null("BattleShockRollCallButton")
if cta == null:
	return "NO_ROLL_CALL_BUTTON"
# The per-unit shortcut row is still there, numbered in resolution order.
var rows = 0
for b in sec.find_children("*", "Button", true, false):
	if String(b.text).begins_with("1."):
		rows += 1
# ...and the whole section must be reachable without scrolling: its button
# has to sit inside the scroll container's visible rect, or a real click
# lands on the container instead (see battleshock_roll_call_sequence).
var scroll = SceneRefs.main_path("HUD_Right/VBoxContainer/CommandScrollContainer")
var in_view = scroll.get_global_rect().encloses(cta.get_global_rect())
return [String(cta.text), rows == 1, in_view]
